window.POETRY_REGISTER("v5-strict-8-11-0-2cf89b45ace9.js",{"poems":[[3110,2],[9971,2],[23635,2],[52804,2],[121861,7],[125885,7],[141934,7],[169925,7],[191152,7],[236151,7],[263614,7],[266880,7],[272119,7],[293900,7],[303050,7],[320915,7],[335947,9],[347962,9],[350997,9],[368392,10],[396622,13],[410396,8],[425746,8],[442638,8],[509536,8],[521039,8],[551648,8],[553578,8],[553742,8],[579306,8],[608049,8],[612302,8],[621290,8],[650074,5],[650374,5],[665013,5],[735220,5]],"pairs":[["幸他人之既不我先","又安能使他人之终不我夺",0],["霜厓缟皓以合沓兮","若长风扇海涌沧溟之波涛",1],["幸他人之既不我先","又安能使他人之终不我夺",2],["否则统依姓名笔划","集中放在无世次一卷之中",3],["业修修兮志与道配","寂不少振兮遽沉幽而终蹇",4],["上不见日兮下可依","吾曳杖兮吾僮以吾之书随",5],["仰不见日兮下可依","吾曳杖兮吾僮以吾之书随",6],["湫灵沸黑兮神物生","云雾昼晦兮风憀栗而凄清",7],["尽向者里钉桩摇橹","新东林为你诸人解缆放船",8],["君不见杜陵桃竹欹","常恐失之君山湖上之风波",9],["醉生梦死真蟪蛄兮","阅千万岁独有贞柏与圣玒",10],["身披凤衣衔虎符兮","控驾三素蹑飞霞而升广寒",11],["惜先生之位弗克究","故先世之志亦终莫之伸也",12],["只知恁么脱空相诳","不知其雠甚于戴天之不共",13],["今夜不免作些方便","为诸人豁开户牖拶碎疑团",14],["祝君以陆地千蹄牛","君言不如扁舟江海狎浮鸥",15],["祝君以通侯尺二组","君言不如草屋三间卧风雨",15],["本利对相思若不还","则告与那能索债愁眉泪眼",16],["今虽不见吾亲颜色","幸得睹此为我永慕之容媒",17],["新也上医国固有道","说也孝感可以假上帝通神",18],["衣荷之叶兮叶易穿","采楟花以为食兮食不下咽",19],["祝君以陆地千蹄牛","君言不如扁舟江海狎浮鸥",20],["祝君以通侯尺二组","君言不如草屋三间卧风雨",20],["君不见近时淮海上","亦有菊花一派往往传京都",21],["天地之位何以云然","俯仰高卑健顺方圆在一字",22],["仙居之山几千仞兮","芙蓉万叠屼然直上而孤撑",23],["秋风萧萧兮云飞扬","白露既降兮百草萎而不芳",24],["丈夫义气烈当如此","谁敢乱把纲常颠倒如波颓",25],["侯生弊衣冠乃上坐","又有浆家博徒相过时见招",26],["览察时物其如此兮","余悲夫孤臣孽子何以为心",27],["吾将正春秋之首恶","又何诛于盛陈莽德之群工",28],["飘然乘风兮凌太虚","参王乔与韩终兮列仙为徒",29],["不肯学龙蛇自委蛇","何不去而海上从彼辟谷仙",30],["安得驾飞龙乘紫烟","直与安期羡门万古长周旋",31],["秋风萧萧兮云飞扬","白露既降兮百草萎而不芳",32],["黄帝平了蚩尤的乱","平稳稳的乾坤又起了争端",33],["渭水打猎作了好梦","添上个惯战能征的姜子牙",33],["元世祖建都直隶省","把一个花花世界喝了甜茶",33],["好一似食尽鸟投林","落了片白茫茫大地真干净",34],["又不得长房缩地方","移取湘帆九面置之几砚角",35],["好一似食尽鸟投林","落了片白茫茫大地真干净",36]]});
